    y = observation.get('y', 0) if isinstance(observation, dict) else 0
    grid = observation.get('grid', None) if isinstance(observation, dict) else None
    width = observation.get('width', None) if isinstance(observation, dict) else None
    height = observation.get('height', None) if isinstance(observation, dict) else None

    # Helper to clamp a delta to allowed range
    def clamp(v):
