        if v > 1:  return 1
        return v

    # Basic steady behavior: try to stay central and avoid edges if possible
    dx = 0
    dy = 0

    # If we have a grid, attempt to stay away from borders
    if width is not None and height is not None:
        # Move away from edges
        if x <= 0:
            dx = 1
        elif x >= width - 1:
            dx = -1
        else:
            dx = 0
        if y <= 0:
            dy = 1
        elif y >= height - 1:
            dy = -1
        else:
            dy = 0

    # If explicit obstacle/goal hints exist, bias toward center or away from threats
    if isinstance(grid, list):
        # heuristics on the local 3x3 neighborhood if present
        # Try to move to a safe cell: prefer no occupancy by detecting truthy obstacles
        # Build a small local map around current position if possible
        if 0 <= y < len(grid):
