        else:
            row = None

        # Simple check: if there is an obstacle at current or adjacent, move away
        # We assume grid[y][x] == 1 means obstacle; adapt defensively
        def is_obst(px, py):
            if not (0 <= py < len(grid)) or not isinstance(grid[py], list):
                return False
            row = grid[py]
            if not (0 <= px < len(row)):
                return False
            return bool(row[px])

        # Prefer to move to a non-obstacle among the 8 neighbors
        best = None
        for ndx in (-1, 0, 1):
            for ndy in (-1, 0, 1):
                if ndx == 0 and ndy == 0:
                    continue
                tx = x + ndx
                ty = y + ndy
                if 0 <= tx < (width if width is not None else 0) and 0 <= ty < (height if height is not None else 0):
                    if not is_obst(tx, ty):
                        best = (ndx, ndy)
                        break
            if best is not None:
                break
        if best is not None:
            dx, dy = best

    # Final normalization to ensure in [-1,1]
    dx = -1 if dx < -1 else 1 if dx > 1 else dx
    dy = -1 if dy < -1 else 1 if dy > 1 else dy

    return [dx, dy]

